document.addEventListener('DOMContentLoaded',()=>{const divisorInput=document.getElementById('divisor-input');const fbNoteToggle=document.getElementById('fb-note-toggle');const saveBtn=document.getElementById('save-btn');const statusDiv=document.getElementById('status');chrome.storage.local.get(['bidEstimateDivisor','fbNoteEnabled'],(result)=>{if(result.bidEstimateDivisor){divisorInput.value=result.bidEstimateDivisor;}if(result.fbNoteEnabled!==undefined){fbNoteToggle.checked=result.fbNoteEnabled;}});saveBtn.addEventListener('click',()=>{const divisor=parseFloat(divisorInput.value);const fbNoteEnabled=fbNoteToggle.checked;if(isNaN(divisor)||divisor<=0){statusDiv.textContent='Please enter a valid number';statusDiv.style.color='#ff4444';setTimeout(()=>{statusDiv.textContent='';statusDiv.style.color='#00ff66';},2000);return;}chrome.storage.local.set({bidEstimateDivisor:divisor,fbNoteEnabled:fbNoteEnabled},()=>{statusDiv.textContent='Saved!';setTimeout(()=>{statusDiv.textContent='';},2000);});});});